//! The stored frame format and wire types (milestone M7).
//!
//! A frame in history is either a full keyframe, a delta crop covering only
//! the pixels changed since the keyframe, or a placeholder marked to be
//! regenerated by replay when the 64 MiB queue was exceeded. Every payload
//! is verified with Castagnoli CRC32-C.
const std = @import("std");
const position_mod = @import("position.zig");

pub const Position = position_mod.Position;
pub const Crc32c = std.hash.crc.@"CRC-32/ISCSI";

pub const FrameKind = enum(u8) {
    keyframe = 1,
    delta = 2,
    regenerate_by_replay = 3,
};

pub const Rect = struct {
    x: u16 = 0,
    y: u16 = 0,
    width: u16 = 0,
    height: u16 = 0,
};

pub const magic: [4]u8 = "RA8F".*;
pub const version: u16 = 1;
pub const header_len: usize = 58;

pub const Error = error{
    Truncated,
    BadMagic,
    BadVersion,
    BadKind,
    BadPosition,
    BadCrc,
    BadPayloadLength,
};

pub const FrameHeader = struct {
    magic: [4]u8 = magic,
    version: u16 = version,
    kind: FrameKind,
    reserved: u8 = 0,
    position: Position,
    virtual_ns: u64,
    width: u16,
    height: u16,
    rect: Rect,
    uncompressed_len: u32,
    compressed_len: u32,
    crc32c: u32,

    pub fn encode(self: FrameHeader, buf: *[header_len]u8) void {
        @memcpy(buf[0..4], &self.magic);
        std.mem.writeInt(u16, buf[4..6], self.version, .little);
        buf[6] = @backingInt(self.kind);
        buf[7] = self.reserved;
        writePositionBytes(buf[8..26], self.position);
        std.mem.writeInt(u64, buf[26..34], self.virtual_ns, .little);
        std.mem.writeInt(u16, buf[34..36], self.width, .little);
        std.mem.writeInt(u16, buf[36..38], self.height, .little);
        std.mem.writeInt(u16, buf[38..40], self.rect.x, .little);
        std.mem.writeInt(u16, buf[40..42], self.rect.y, .little);
        std.mem.writeInt(u16, buf[42..44], self.rect.width, .little);
        std.mem.writeInt(u16, buf[44..46], self.rect.height, .little);
        std.mem.writeInt(u32, buf[46..50], self.uncompressed_len, .little);
        std.mem.writeInt(u32, buf[50..54], self.compressed_len, .little);
        std.mem.writeInt(u32, buf[54..58], self.crc32c, .little);
    }

    pub fn writeTo(self: FrameHeader, writer: anytype) !void {
        var buf: [header_len]u8 = undefined;
        self.encode(&buf);
        try writer.writeAll(&buf);
    }

    pub fn decode(bytes: []const u8) Error!FrameHeader {
        if (bytes.len < header_len) return Error.Truncated;
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return Error.BadMagic;
        const ver = std.mem.readInt(u16, bytes[4..6], .little);
        if (ver != version) return Error.BadVersion;
        const kind: FrameKind = switch (bytes[6]) {
            1 => .keyframe,
            2 => .delta,
            3 => .regenerate_by_replay,
            else => return Error.BadKind,
        };
        const reserved = bytes[7];
        var at: usize = 0;
        const pos = position_mod.decode(bytes[8..26], &at) catch return Error.BadPosition;
        const virtual_ns = std.mem.readInt(u64, bytes[26..34], .little);
        const width = std.mem.readInt(u16, bytes[34..36], .little);
        const height = std.mem.readInt(u16, bytes[36..38], .little);
        const rx = std.mem.readInt(u16, bytes[38..40], .little);
        const ry = std.mem.readInt(u16, bytes[40..42], .little);
        const rw = std.mem.readInt(u16, bytes[42..44], .little);
        const rh = std.mem.readInt(u16, bytes[44..46], .little);
        const uncompressed_len = std.mem.readInt(u32, bytes[46..50], .little);
        const compressed_len = std.mem.readInt(u32, bytes[50..54], .little);
        const crc = std.mem.readInt(u32, bytes[54..58], .little);
        return .{
            .magic = magic,
            .version = ver,
            .kind = kind,
            .reserved = reserved,
            .position = pos,
            .virtual_ns = virtual_ns,
            .width = width,
            .height = height,
            .rect = .{ .x = rx, .y = ry, .width = rw, .height = rh },
            .uncompressed_len = uncompressed_len,
            .compressed_len = compressed_len,
            .crc32c = crc,
        };
    }

    pub fn computeCrc(payload: []const u8) u32 {
        if (payload.len == 0) return 0;
        return Crc32c.hash(payload);
    }

    pub fn verifyCrc(self: FrameHeader, payload: []const u8) bool {
        if (payload.len != self.compressed_len) return false;
        if (self.compressed_len == 0) return self.crc32c == 0;
        return self.crc32c == computeCrc(payload);
    }
};

fn writePositionBytes(buf: []u8, pos: Position) void {
    std.mem.writeInt(u32, buf[0..4], pos.branch, .little);
    std.mem.writeInt(u64, buf[4..12], pos.r, .little);
    buf[12] = @backingInt(pos.phase);
    std.mem.writeInt(u32, buf[13..17], pos.o, .little);
    buf[17] = @backingInt(pos.gap);
}

pub const FrameRecord = struct {
    header: FrameHeader,
    payload: []const u8,

    pub fn deinit(self: *FrameRecord, allocator: std.mem.Allocator) void {
        if (self.payload.len != 0) {
            allocator.free(self.payload);
            self.payload = &.{};
        }
    }

    pub fn writeTo(self: FrameRecord, writer: anytype) !void {
        try self.header.writeTo(writer);
        if (self.payload.len != 0) try writer.writeAll(self.payload);
    }

    pub fn decode(allocator: std.mem.Allocator, bytes: []const u8) !FrameRecord {
        const header = try FrameHeader.decode(bytes);
        const total = header_len + header.compressed_len;
        if (bytes.len < total) return Error.Truncated;
        const payload_slice = bytes[header_len..total];
        if (!header.verifyCrc(payload_slice)) return Error.BadCrc;
        const owned_payload = if (header.compressed_len > 0)
            try allocator.dupe(u8, payload_slice)
        else
            &.{};
        return .{ .header = header, .payload = owned_payload };
    }
};

/// Sink interface for receiving processed frame records from CompositorWorker.
/// `writeFrame` borrows `record` and its payload for the duration of the call.
/// The caller retains ownership of the payload buffer and frees it upon return.
/// Sinks that retain the payload past the call must duplicate it.
pub const FrameSink = struct {
    ctx: *anyopaque,
    writeFrameFn: *const fn (ctx: *anyopaque, record: *const FrameRecord) anyerror!void,

    pub fn writeFrame(self: FrameSink, record: *const FrameRecord) !void {
        return self.writeFrameFn(self.ctx, record);
    }
};
